-- Full Local SEO System Database Dump
CREATE DATABASE IF NOT EXISTS `seo_system` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `seo_system`;

DROP TABLE IF EXISTS `backlink_queue`;
CREATE TABLE `backlink_queue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `social_account_id` int(11) NOT NULL,
  `platform` varchar(50) NOT NULL,
  `keyword` varchar(255) NOT NULL,
  `target_url` varchar(255) NOT NULL,
  `status` enum('pending','processing','success','failed') DEFAULT 'pending',
  `published_url` varchar(255) DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `post_image` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `backlinks`;
CREATE TABLE `backlinks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `backlink_url` varchar(1000) NOT NULL,
  `platform` varchar(100) DEFAULT NULL,
  `da_score` int(11) DEFAULT 0,
  `status` enum('pending','created','verified') DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `post_title` varchar(500) DEFAULT NULL,
  `verified_status` varchar(50) DEFAULT 'unverified',
  `last_checked_at` datetime DEFAULT NULL,
  `keyword` varchar(255) DEFAULT NULL,
  `target_url` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `backlinks_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2574 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `broken_internal_links`;
CREATE TABLE `broken_internal_links` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `source_url` varchar(255) NOT NULL,
  `broken_url` varchar(255) NOT NULL,
  `status_code` int(11) NOT NULL,
  `found_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `content_queue`;
CREATE TABLE `content_queue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `title` varchar(500) DEFAULT NULL,
  `article` longtext DEFAULT NULL,
  `status` enum('draft','approved','published') DEFAULT 'draft',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `content_queue_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `keyword_rankings_log`;
CREATE TABLE `keyword_rankings_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `keyword` varchar(255) NOT NULL,
  `position` int(11) NOT NULL,
  `logged_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `keywords`;
CREATE TABLE `keywords` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `keyword` varchar(255) NOT NULL,
  `search_volume` int(11) DEFAULT 0,
  `difficulty` int(11) DEFAULT 0,
  `selected` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `cpc` decimal(5,2) DEFAULT 0.00,
  `seo_difficulty` int(11) DEFAULT NULL,
  `competition` float DEFAULT 0,
  `score` int(11) DEFAULT 0,
  `status` varchar(20) DEFAULT 'Pending',
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `keywords_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1253 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `onpage_issues`;
CREATE TABLE `onpage_issues` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `issue_type` varchar(100) DEFAULT NULL,
  `issue_detail` text DEFAULT NULL,
  `fix_code` text DEFAULT NULL,
  `status` enum('open','approved','fixed') DEFAULT 'open',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `onpage_issues_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=386 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `project_meta`;
CREATE TABLE `project_meta` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `meta_title` varchar(100) NOT NULL,
  `meta_description` varchar(200) NOT NULL,
  `meta_keywords` text DEFAULT NULL,
  `og_title` varchar(120) DEFAULT NULL,
  `og_description` varchar(220) DEFAULT NULL,
  `og_image` varchar(500) DEFAULT NULL,
  `h1_suggestion` varchar(255) DEFAULT NULL,
  `schema_json` longtext DEFAULT NULL,
  `full_head_html` longtext DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_id` (`project_id`),
  CONSTRAINT `project_meta_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `website_url` varchar(500) NOT NULL,
  `target_keyword` varchar(255) NOT NULL,
  `target_site` varchar(500) DEFAULT NULL,
  `seo_score` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `post_image` varchar(255) DEFAULT NULL,
  `auto_schedule` tinyint(1) DEFAULT 1,
  `package_type` varchar(50) DEFAULT 'basic',
  `business_name` varchar(255) DEFAULT '',
  `contact_name` varchar(255) DEFAULT '',
  `phone` varchar(50) DEFAULT '',
  `email` varchar(255) DEFAULT '',
  `gsc_access` text DEFAULT NULL,
  `ga_access` text DEFAULT NULL,
  `admin_url` varchar(255) DEFAULT '',
  `admin_user` varchar(255) DEFAULT '',
  `admin_pass` text DEFAULT NULL,
  `competitor_sites` text DEFAULT NULL,
  `business_desc` text DEFAULT NULL,
  `business_address` text DEFAULT NULL,
  `business_hours` varchar(255) DEFAULT NULL,
  `google_ads_id` varchar(100) DEFAULT NULL,
  `onboarding_submitted` int(11) DEFAULT 0,
  `onboarding_submitted_at` datetime DEFAULT NULL,
  `pagespeed_mobile_score` int(11) DEFAULT NULL,
  `pagespeed_desktop_score` int(11) DEFAULT NULL,
  `pagespeed_metrics_json` text DEFAULT NULL,
  `pagespeed_checked_at` datetime DEFAULT NULL,
  `pagespeed_score` int(11) DEFAULT NULL,
  `local_code_path` varchar(255) DEFAULT '',
  `git_repo_url` varchar(255) DEFAULT '',
  `github_user` varchar(255) DEFAULT '',
  `github_token` varchar(255) DEFAULT '',
  `seo_schema_markup` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `projects_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `rank_history`;
CREATE TABLE `rank_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `keyword` varchar(255) DEFAULT NULL,
  `rank_position` int(11) DEFAULT NULL,
  `checked_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `rank_history_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=342 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `seo_reports`;
CREATE TABLE `seo_reports` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NOT NULL,
  `rank` int(11) DEFAULT 0,
  `seo_score` int(11) DEFAULT 0,
  `backlinks_count` int(11) DEFAULT 0,
  `issues_found` text DEFAULT NULL,
  `report_date` date NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  CONSTRAINT `seo_reports_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=243 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `social_accounts`;
CREATE TABLE `social_accounts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `platform` varchar(50) NOT NULL,
  `username` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `password` text DEFAULT NULL,
  `api_key` text DEFAULT NULL,
  `api_secret` text DEFAULT NULL,
  `status` enum('active','inactive') DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `refresh_token` text DEFAULT NULL,
  `project_id` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `social_accounts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(100) NOT NULL,
  `password` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `role` varchar(50) DEFAULT 'admin',
  `allowed_menus` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


